#!/usr/bin/env node
/**
 * 前端 ↔ 后端命令一致性守护（M1-S4 spec §7 / §8.2）。
 *
 * 三件事：
 * 1. `src-tauri/src/commands_list.rs` 的 `COMMANDS` 与 `src/lib/api.ts` 的
 *    `INVOKED_COMMANDS` 必须是**同一个集合**（少一个 = 有命令没人调，多一个 = 调了不存在的命令）；
 * 2. `src-tauri/capabilities/default.json` 必须为每条命令声明 `allow-<kebab-case>`；
 * 3. **只有** `src/lib/api.ts` 允许 `import("@tauri-apps/api")`，页面组件必须走 api 层。
 * 4. `src-tauri/permissions/autogenerated/` 的文件集合必须与 `COMMANDS` 相同（B-25：
 *    命令改名/删除后旧文件不会被 `tauri-build` 清理，幽灵文件会让 `git status` 变脏）。
 *
 * 退出码非 0 即失败，供 `pnpm test` 使用。
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function fail(message) {
  console.error(`✗ ${message}`);
  process.exitCode = 1;
}

/**
 * 打印一项通过。
 *
 * **一旦已经失败过就不再打印 ✓**（P3-17 / DEBUG-REPORT-v3 §3-17）：此前 5b 节会出现
 * 「先 ✗ 后 ✓」的日志，读起来像「前面那个 ✗ 只是提示」。日志必须单调：
 * 通过的项打在前面，从第一处 ✗ 起连续输出失败，不再穿插 ✓。
 */
let suppressedOk = 0;
function ok(message) {
  if (process.exitCode) {
    suppressedOk += 1;
    return;
  }
  console.log(`✓ ${message}`);
}

/**
 * 去掉注释，避免把被注释掉的命令/通道也算进来（否则「删一条命令」抓不到）。
 *
 * **块注释也必须去**（M8-S5B 独立复审 P2-1）：只去行注释时，把一条 `CHANNELS`
 * 条目用 `/* … *\/` 包起来就能让前端清单少一项而脚本照旧绿——
 * 独立复审在沙箱里复现过这个「静默通过」。顺序也有讲究：**先去块注释**，
 * 否则块注释里出现的 `//` 会先把块注释切成两半，剩下的 `*\/` 变成普通文本。
 */
function stripComments(text) {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/[^\n]*/g, "");
}

/** 从 `pub const COMMANDS: &[&str] = &[ "a", "b" ];` 里取出字符串字面量 */
function parseRustCommands() {
  const source = readFileSync(
    join(root, "src-tauri/src/commands_list.rs"),
    "utf8",
  );
  const block = source.match(/pub const COMMANDS[^=]*=\s*&\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 commands_list.rs 里找不到 COMMANDS 数组");
  return [...stripComments(block[1]).matchAll(/"([^"]+)"/g)].map(
    (m) => m[1],
  );
}

/**
 * 从 `src/lib/api.ts` 里取出**真实被调用的**命令名。
 *
 * 解析的是 `invokeCommand<...>("cmd"` 这个调用点，而**不是**某个手工维护的镜像数组——
 * 镜像数组是假守护：把真实调用注释掉、数组不动，检查依然全绿
 * （M1-S3/S4 复审 P1 实测）。
 */
function parseTsCommands() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const calls = [
    ...source.matchAll(/invokeCommand(?:<[^>]*>)?\(\s*"([a-z_]+)"/g),
  ].map((m) => m[1]);
  if (calls.length === 0) {
    throw new Error(
      "在 api.ts 里没解析到任何 invokeCommand(\"…\") 调用——解析器坏了，不能当成通过",
    );
  }
  return [...new Set(calls)];
}

/**
 * 从 `DeliveryChannel::as_str()` 的穷尽 match 里取出通道名字面量（B-101）。
 *
 * 为什么这是**可证伪**的读法：`as_str` 是穷尽 `match`，新增一个 `DeliveryChannel`
 * 变体而忘了加臂，rustc 直接报错 ⇒ 抽出来的臂数与 `ALL` 数组长度必然相等。
 * 反过来，若哪天有人把 `as_str` 改成 `#[derive]` 自动生成，这里的正则会匹配不到
 * 臂 ⇒ **宁可红，也不静默跳过**（解析器失效时报错，不当成通过）。
 */
function parseRustChannels() {
  const source = stripComments(
    readFileSync(join(root, "crates/keyrelay-core/src/delivery/mod.rs"), "utf8"),
  );
  // 只取 `as_str()` **函数体内**的臂：同一个文件里 `agent_id()` 也是同形态的 match，
  // 不限定函数就会把两份都抓进来（实测 14 条臂 vs ALL 的 7 个元素）。
  const fn = source.match(/pub fn as_str\(self\)[\s\S]*?\n    \}/);
  if (!fn) throw new Error("在 delivery/mod.rs 里找不到 as_str() 函数");
  const arms = [
    ...fn[0].matchAll(/DeliveryChannel::(\w+)\s*=>\s*"([a-z0-9-]+)"/g),
  ].map((m) => m[2]);
  if (arms.length === 0) {
    throw new Error(
      "在 delivery/mod.rs 里没解析到任何 DeliveryChannel 的 as_str 臂——解析器坏了，不能当成通过",
    );
  }
  // `ALL` 数组：与臂数对账，防「as_str 加了臂但 ALL 没加」这种半边改动
  const all = source.match(/pub const ALL[^=]*=\s*\[([\s\S]*?)\]/);
  if (!all) throw new Error("在 delivery/mod.rs 里找不到 DeliveryChannel::ALL");
  const allCount = [...all[1].matchAll(/DeliveryChannel::\w+/g)].length;
  if (allCount !== arms.length) {
    throw new Error(
      `DeliveryChannel::ALL 有 ${allCount} 个元素，但 as_str 有 ${arms.length} 条臂——两边不同步`,
    );
  }
  return arms;
}

/**
 * 从 `src/pages/Agents.tsx` 的 `CHANNELS` 数组里取出 id 字面量。
 *
 * 前端那份是**手工维护**的（界面要拿它渲染下拉），所以必须与后端对账：
 * 少了 ⇒ 用户选不到新通道；多了 ⇒ 选到一个后端不认识的通道。
 */
function parseTsChannels() {
  const source = stripComments(
    readFileSync(join(root, "src/pages/Agents.tsx"), "utf8"),
  );
  const block = source.match(/const CHANNELS\s*=\s*\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 Agents.tsx 里找不到 CHANNELS 数组");
  const ids = [...block[1].matchAll(/id:\s*"([a-z0-9-]+)"/g)].map((m) => m[1]);
  if (ids.length === 0) {
    throw new Error(
      "在 Agents.tsx 的 CHANNELS 里没解析到任何 id——解析器坏了，不能当成通过",
    );
  }
  return ids;
}

/**
 * 从 `src/lib/api.ts` 的 `AGENT_CHANNELS` 表里取出 channel id 字面量（M8-S7 / B-116）。
 *
 * 为什么单独对账：这张表服务「从一条 binding 反查它属于哪条通道」
 * （`channelOfBinding`），**`CHANNELS` 的对账覆盖不到它**——两边漏一条的后果不一样：
 * `CHANNELS` 漏了用户选不到；`AGENT_CHANNELS` 漏了该行显示「无法识别通道」，
 * 用户没办法批量改指它，而**没有任何东西会红**（M8-S7 独立复审 P2-1）。
 *
 * 与 `CHANNELS` 分开断言而不是取并集：并集会让「两边都漏同一条」互相掩护。
 */
function parseTsAgentChannels() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const block = source.match(/const AGENT_CHANNELS[^=]*=\s*\{([\s\S]*?)\n\};/);
  if (!block) throw new Error("在 api.ts 里找不到 AGENT_CHANNELS 表");
  // `Record<string, string>`：取值就是 channel id 字面量
  const ids = [...block[1].matchAll(/:\s*"([a-z0-9-]+)"/g)].map((m) => m[1]);
  if (ids.length === 0) {
    throw new Error(
      "在 api.ts 的 AGENT_CHANNELS 里没解析到任何 channel id——解析器坏了，不能当成通过",
    );
  }
  // agent 键也要与后端 `agent_id()` 的臂对账：键漏了 ⇒ 那个 agent 的绑定全查不到通道
  // `Record<string, string>`：键在行首（可能带引号），取值是字符串
  const keys = [...block[1].matchAll(/^\s{2}["']?([a-z0-9-]+)["']?:\s*"/gm)].map(
    (m) => m[1],
  );
  if (keys.length === 0) {
    throw new Error(
      "在 api.ts 的 AGENT_CHANNELS 里没解析到任何 agent 键——解析器坏了，不能当成通过",
    );
  }
  return { ids, keys };
}

/** 后端 `DeliveryChannel::agent_id()` 的臂（与 `as_str` 同形态，只是函数名不同）。 */
function parseRustAgentIds() {
  const source = stripComments(
    readFileSync(join(root, "crates/keyrelay-core/src/delivery/mod.rs"), "utf8"),
  );
  const fn = source.match(/pub fn agent_id\(self\)[\s\S]*?\n    \}/);
  if (!fn) throw new Error("在 delivery/mod.rs 里找不到 agent_id() 函数");
  const arms = [...fn[0].matchAll(/DeliveryChannel::\w+\s*=>\s*"([a-z0-9-]+)"/g)].map(
    (m) => m[1],
  );
  if (arms.length === 0) {
    throw new Error(
      "在 delivery/mod.rs 的 agent_id() 里没解析到任何臂——解析器坏了，不能当成通过",
    );
  }
  return arms;
}

function parseCapabilities() {
  const raw = readFileSync(
    join(root, "src-tauri/capabilities/default.json"),
    "utf8",
  );
  return JSON.parse(raw).permissions ?? [];
}

/** `list_sites` → `allow-list-sites`（Tauri 的权限名映射规则） */
function permissionFor(command) {
  return `allow-${command.replace(/_/g, "-")}`;
}

function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (/\.(ts|tsx)$/.test(entry)) out.push(full);
  }
  return out;
}

// ---------------------------------------------------------------- 1. 集合一致性

const rust = parseRustCommands();
const ts = parseTsCommands();

const onlyRust = rust.filter((c) => !ts.includes(c));
const onlyTs = ts.filter((c) => !rust.includes(c));

if (onlyRust.length) {
  fail(`后端有、前端未覆盖的命令：${onlyRust.join(", ")}`);
} else if (onlyTs.length) {
  fail(`前端调用了不存在的命令：${onlyTs.join(", ")}`);
} else {
  ok(`命令集合一致（${rust.length} 条）`);
}

// ---------------------------------------------------------------- 2. capabilities

const permissions = parseCapabilities();
const missing = rust
  .map(permissionFor)
  .filter((p) => !permissions.includes(p));

if (missing.length) {
  fail(`capabilities 缺少权限声明：${missing.join(", ")}`);
} else {
  ok(`capabilities 覆盖全部 ${rust.length} 条命令`);
}

// ---------------------------------------------------------------- 3. 唯一入口

const srcFiles = walk(join(root, "src"));
const offenders = srcFiles
  .filter((file) => relative(root, file) !== "src/lib/api.ts")
  // 先去掉注释再查（M16-S6b）：裸子串检查会把「注释里提到 @tauri-apps/api」也算成违规，
  // 而注释不会 import 任何东西——那是一条**假红**，会训练大家不敢在文档里写包名。
  // 去注释只会减少假红，不会放过真实违规（真 import 在代码里，不在注释里）。
  .filter((file) => stripComments(readFileSync(file, "utf8")).includes("@tauri-apps/api"));

if (offenders.length) {
  fail(
    `只有 src/lib/api.ts 可以直接引用 @tauri-apps/api，违规文件：\n  ${offenders
      .map((f) => relative(root, f))
      .join("\n  ")}`,
  );
} else {
  ok("只有 src/lib/api.ts 直接引用 @tauri-apps/api");
}

// ------------------------------------------------- 4. 权限生成物 == 命令集合（B-25）

/**
 * `tauri-build` 按 `COMMANDS` 生成 `src-tauri/permissions/autogenerated/<command>.toml`。
 * 命令改名 / 删除后旧文件**不会被清理**（M1-S1 的 `zz_ghost_probe.toml` 就是这么留下的，
 * 源码恢复后它还在，`git status` 因此变脏），而「没跑过构建」又会表现为缺文件。
 * 所以两个方向都要红，并且报错必须直接指出**哪个文件 / 哪条命令**。
 */
const AUTOGENERATED_DIR = join(root, "src-tauri/permissions/autogenerated");

function listAutogeneratedFiles() {
  let entries;
  try {
    entries = readdirSync(AUTOGENERATED_DIR, { withFileTypes: true });
  } catch (error) {
    throw new Error(
      `读不到 ${relative(root, AUTOGENERATED_DIR)}/（${error.code}）。` +
        "该目录的生成物是**入库**的（B-25），缺失说明它被删了或被 .gitignore 掉了",
    );
  }
  return (
    entries
      .filter((entry) => entry.isFile())
      // macOS 的 Finder 会往目录里塞 .DS_Store；它不是权限生成物，不算幽灵
      .filter((entry) => !entry.name.startsWith("."))
      .map((entry) => entry.name)
      .sort()
  );
}

const expectedPermissionFiles = rust.map((command) => `${command}.toml`).sort();
const actualPermissionFiles = listAutogeneratedFiles();

const ghostFiles = actualPermissionFiles.filter(
  (file) => !expectedPermissionFiles.includes(file),
);
const missingFiles = expectedPermissionFiles.filter(
  (file) => !actualPermissionFiles.includes(file),
);

// 两个方向**分别**报，不写成 if/else（M5-S6 复审 P2-1）：
// 幽灵与缺失同时存在时，只报前者会让「构建没跑过 / 生成物被删」这条线索完全消失。
if (ghostFiles.length) {
  fail(
    `权限目录里有**幽灵文件**（COMMANDS 里没有对应的命令，tauri-build 不会清理）：\n  ${ghostFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（COMMANDS 里没有「${file.replace(
            /\.toml$/,
            "",
          )}」）`,
      )
      .join("\n  ")}\n  处理：确认命令确实已改名 / 删除后，手动删掉这些文件（B-25）`,
  );
}
if (missingFiles.length) {
  fail(
    `权限目录**缺少生成物**（命令在 COMMANDS 里，却没有对应的权限文件）：\n  ${missingFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（在 src-tauri/ 跑一次构建会生成它）`,
      )
      .join("\n  ")}`,
  );
}
if (!ghostFiles.length && !missingFiles.length) {
  ok(
    `权限生成物与命令集合一致（${actualPermissionFiles.length} 个文件 == ${rust.length} 条命令）`,
  );
}

// ---------------------------------------------------------------- 5. 通道名对账（B-101）
// 前端 `CHANNELS` 的 id 集合必须与后端 `DeliveryChannel::ALL` 的 `as_str()` 集合相同。
// 少一个 ⇒ 用户选不到新通道；多一个 ⇒ 选到一个后端不认识的通道。
const rustChannels = parseRustChannels();
const tsChannels = parseTsChannels();
const onlyBackend = rustChannels.filter((c) => !tsChannels.includes(c));
const onlyFrontend = tsChannels.filter((c) => !rustChannels.includes(c));
if (onlyBackend.length || onlyFrontend.length) {
  fail(
    `投递通道名两边不一致（B-101）：\n` +
      (onlyBackend.length
        ? `  只有后端有: ${onlyBackend.join(", ")}\n`
        : "") +
      (onlyFrontend.length
        ? `  只有前端有: ${onlyFrontend.join(", ")}（后端不认识的通道，用户选到了也发不出去）\n`
        : "") +
      `  后端清单来自 delivery/mod.rs 的 as_str()（${rustChannels.length} 条），` +
      `前端清单来自 Agents.tsx 的 CHANNELS（${tsChannels.length} 条）`,
  );
} else {
  ok(`投递通道名两边一致（${rustChannels.length} 条）`);
}

// ------------------------------------------- 5b. AGENT_CHANNELS 对账（M8-S7 / B-116 P2-1）
// `channelOfBinding` 用的第二张前端表。`CHANNELS` 的对账覆盖不到它，
// 而它漏一条的后果是「该通道无法批量改指」且无任何东西会红。
const agentTable = parseTsAgentChannels();
const rustChannelsForAgent = parseRustChannels();
const rustAgentIds = parseRustAgentIds();

// ① channel id 集合：AGENT_CHANNELS ∪ CHANNELS == 后端 as_str()
const agentOnly = agentTable.ids.filter((c) => !rustChannelsForAgent.includes(c));
const missingFromAgent = rustChannelsForAgent.filter((c) => !agentTable.ids.includes(c));
if (agentOnly.length || missingFromAgent.length) {
  fail(
    `AGENT_CHANNELS 与后端通道名不一致（M8-S7 / B-116）：\n` +
      (missingFromAgent.length
        ? `  后端有、表里没有: ${missingFromAgent.join(", ")}（这些通道无法批量改指）\n`
        : "") +
      (agentOnly.length
        ? `  只有表里有: ${agentOnly.join(", ")}（后端不认识的通道）\n`
        : "") +
      `  表在 src/lib/api.ts 的 AGENT_CHANNELS`,
  );
}

// ② agent 键集合 == 后端 agent_id() 的臂
const agentKeyOnly = agentTable.keys.filter((a) => !rustAgentIds.includes(a));
const agentIdMissing = rustAgentIds.filter((a) => !agentTable.keys.includes(a));
if (agentKeyOnly.length || agentIdMissing.length) {
  fail(
    `AGENT_CHANNELS 的 agent 键与后端 agent_id() 不一致：\n` +
      (agentIdMissing.length
        ? `  后端有、表里没有: ${agentIdMissing.join(", ")}（这些 agent 的绑定查不到通道）\n`
        : "") +
      (agentKeyOnly.length
        ? `  只有表里有: ${agentKeyOnly.join(", ")}\n`
        : ""),
  );
}

// ③ 两侧表各自的 id 集合必须相同（防「两边都漏同一条」互相掩护）
const frontOnlyAgent = agentTable.ids.filter((c) => !tsChannels.includes(c));
const frontOnlyChannels = tsChannels.filter((c) => !agentTable.ids.includes(c));
if (frontOnlyAgent.length || frontOnlyChannels.length) {
  fail(
    `前端两张表的 channel id 不一致（CHANNELS vs AGENT_CHANNELS）：\n` +
      (frontOnlyChannels.length ? `  只有 CHANNELS 有: ${frontOnlyChannels.join(", ")}\n` : "") +
      (frontOnlyAgent.length ? `  只有 AGENT_CHANNELS 有: ${frontOnlyAgent.join(", ")}\n` : ""),
  );
} else {
  // P3-17 / DEBUG-REPORT-v3 §3-17：文案只说 ③ 自己检查的（前端两张表 id 集合一致），
  // 不提「与后端对账」——那是 ①② 的职责。
  ok(
    `CHANNELS 与 AGENT_CHANNELS 的 channel id 集合一致（${agentTable.ids.length} 条 / ${agentTable.keys.length} 个 agent）`,
  );
}

// ============================================ 6. 通道 ↔ agent 的**配对**（P2-17 G4/G5）
//
// 为什么 id 集合相等还不够：两张表各自与后端比的是**集合**，把
// `AGENT_CHANNELS["codex"]` 从 `codex-auth-json` 改成 `claude-code-settings`
// （或把 `CHANNELS` 里某条的 `agent` 写错）时，三个集合一字未变 ⇒ 全绿通过。
// 而后果是实打实的：`channelOfBinding("codex")` 会返回错的通道，批量改指把
// **另一个 agent 的落点**当成 codex 的目标；解绑也会按错的 agent 找绑定。
// 所以必须比**配对**，不是比集合。

/** 后端 `(channel, agent)` 的配对表：`as_str()` 与 `agent_id()` 的臂按变体名对齐。 */
function parseRustChannelAgentPairs() {
  const source = stripComments(
    readFileSync(join(root, "crates/keyrelay-core/src/delivery/mod.rs"), "utf8"),
  );
  const armsOf = (fnName) => {
    const fn = source.match(new RegExp(`pub fn ${fnName}\\(self\\)[\\s\\S]*?\\n    \\}`));
    if (!fn) throw new Error(`在 delivery/mod.rs 里找不到 ${fnName}() 函数`);
    const arms = new Map();
    for (const m of fn[0].matchAll(/DeliveryChannel::(\w+)\s*=>\s*"([a-z0-9-]+)"/g)) {
      arms.set(m[1], m[2]);
    }
    if (arms.size === 0) {
      throw new Error(`${fnName}() 里没解析到任何臂——解析器坏了，不能当成通过`);
    }
    return arms;
  };
  const channels = armsOf("as_str");
  const agents = armsOf("agent_id");
  if (channels.size !== agents.size) {
    throw new Error(
      `as_str() 有 ${channels.size} 条臂、agent_id() 有 ${agents.size} 条臂——两边不同步`,
    );
  }
  const pairs = [];
  for (const [variant, channel] of channels) {
    const agent = agents.get(variant);
    if (!agent) {
      throw new Error(`as_str() 有 ${variant} 而 agent_id() 没有——两边臂不同步`);
    }
    pairs.push({ variant, channel, agent });
  }
  return pairs;
}

/** `AGENT_CHANNELS` 的**映射**（agent → channel）；集合形态由 5b 节另测。 */
function parseTsAgentChannelMap() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const block = source.match(/const AGENT_CHANNELS[^=]*=\s*\{([\s\S]*?)\n\};/);
  if (!block) throw new Error("在 api.ts 里找不到 AGENT_CHANNELS 表");
  const map = new Map();
  for (const m of block[1].matchAll(/^\s{2}["']?([a-z0-9-]+)["']?\s*:\s*"([a-z0-9-]+)"/gm)) {
    map.set(m[1], m[2]);
  }
  if (map.size === 0) {
    throw new Error("AGENT_CHANNELS 里没解析到任何配对——解析器坏了，不能当成通过");
  }
  return map;
}

/** `Agents.tsx` 的 `CHANNELS` 条目 → `(channel, agent)` 配对。 */
function parseTsChannelPairs() {
  const source = stripComments(
    readFileSync(join(root, "src/pages/Agents.tsx"), "utf8"),
  );
  const block = source.match(/const CHANNELS\s*=\s*\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 Agents.tsx 里找不到 CHANNELS 数组");
  const pairs = [];
  for (const m of block[1].matchAll(
    /id:\s*"([a-z0-9-]+)",\s*label:\s*"[^"]*",\s*agent:\s*"([a-z0-9-]+)"/g,
  )) {
    pairs.push({ channel: m[1], agent: m[2] });
  }
  if (pairs.length === 0) {
    throw new Error("CHANNELS 里没解析到任何 (id, agent) 配对——解析器坏了，不能当成通过");
  }
  return pairs;
}

const rustPairs = parseRustChannelAgentPairs();
const tsAgentMap = parseTsAgentChannelMap();
const tsChannelPairs = parseTsChannelPairs();

{
  const problems = [];
  // ① 后端每一对，前端两张表都要有**同一对**
  for (const { channel, agent } of rustPairs) {
    const inAgentTable = tsAgentMap.get(agent);
    if (inAgentTable !== channel) {
      problems.push(
        `  AGENT_CHANNELS["${agent}"] = ${inAgentTable ? `"${inAgentTable}"` : "（缺）"}，` +
          `后端是 "${channel}"`,
      );
    }
    const entry = tsChannelPairs.find((p) => p.channel === channel);
    if (!entry) {
      problems.push(`  CHANNELS 里缺通道 "${channel}"`);
    } else if (entry.agent !== agent) {
      problems.push(
        `  CHANNELS 里 "${channel}" 的 agent 是 "${entry.agent}"，后端是 "${agent}"`,
      );
    }
  }
  // ② 前端多出来的配对也要报（反向）
  const rustByChannel = new Map(rustPairs.map((p) => [p.channel, p.agent]));
  for (const [agent, channel] of tsAgentMap) {
    if (!rustByChannel.has(channel)) {
      problems.push(`  AGENT_CHANNELS["${agent}"] = "${channel}"：后端没有这个通道`);
    }
  }
  for (const { channel, agent } of tsChannelPairs) {
    const expected = rustByChannel.get(channel);
    if (expected === undefined) {
      problems.push(`  CHANNELS 里有后端不认识的通道 "${channel}"`);
    }
  }
  if (problems.length) {
    fail(
      `通道 ↔ agent 的**配对**与后端不一致（P2-17 G4/G5）：\n${problems.join("\n")}\n` +
        `  后端配对来自 delivery/mod.rs 的 as_str() × agent_id()（${rustPairs.length} 对）；` +
        `  前端来自 api.ts 的 AGENT_CHANNELS 与 Agents.tsx 的 CHANNELS`,
    );
  } else {
    ok(`通道 ↔ agent 配对两边一致（${rustPairs.length} 对）`);
  }
}

// ============================================ 7. generate_handler! 注册（P2-17 G6）
//
// `COMMANDS` 是给权限生成物与命令表用的；真正决定「这条命令能不能被 invoke」
// 的是 `lib.rs` 里的 `tauri::generate_handler![…]`。漏注册时：
// 命令表、capabilities、autogenerated 权限文件、api.ts 调用点**全都一致**，
// 前端点下去只得到「command not found」——而没有任何东西会红。

function parseGenerateHandler() {
  const source = stripComments(
    readFileSync(join(root, "src-tauri/src/lib.rs"), "utf8"),
  );
  const block = source.match(/generate_handler!\[([\s\S]*?)\]/);
  if (!block) {
    throw new Error(
      "在 src-tauri/src/lib.rs 里找不到 generate_handler![…]——解析器坏了，不能当成通过",
    );
  }
  const names = [...block[1].matchAll(/commands::([a-z_][a-z0-9_]*)/g)].map((m) => m[1]);
  if (names.length === 0) {
    throw new Error("generate_handler![…] 里没解析到任何 commands::X——不能当成通过");
  }
  return names;
}

{
  const registered = parseGenerateHandler();
  const notRegistered = rust.filter((c) => !registered.includes(c));
  const notInTable = registered.filter((c) => !rust.includes(c));
  if (notRegistered.length || notInTable.length) {
    fail(
      `generate_handler! 与 COMMANDS 不一致（P2-17 G6）：\n` +
        (notRegistered.length
          ? `  在 COMMANDS 里但没注册（前端点下去只会得到 command not found）: ${notRegistered.join(", ")}\n`
          : "") +
        (notInTable.length
          ? `  注册了但不在 COMMANDS 里（权限文件与 capabilities 都覆盖不到它）: ${notInTable.join(", ")}\n`
          : "") +
        `  注册表在 src-tauri/src/lib.rs 的 generate_handler![…]`,
    );
  } else {
    ok(`generate_handler! 注册与 COMMANDS 一致（${registered.length} 条）`);
  }
}

// ============================================ 8. 命令参数名（P2-17 G7）
//
// Tauri 2 按**参数名**把 JS 传的对象反序列化进命令的形参。把 `siteId` 写成
// `site_id`（或拼错一个字母）时，命令表 / capabilities / 权限文件 / 调用点仍然
// 四边一致 ⇒ 全绿，而运行时是「missing required key siteId」。
// 所以要对账**每条命令的形参名（camelCase）**与**调用点传的键**。

/** Rust 命令的形参名（去掉 Tauri 注入的 `state` / `app` 等），camelCase。 */
function parseRustCommandParams() {
  const source = stripComments(
    readFileSync(join(root, "src-tauri/src/commands.rs"), "utf8"),
  );
  const INJECTED = /^(State|AppHandle|Window|WebviewWindow|Webview)\b/;
  const map = new Map();
  // 泛型参数也要吃掉：`pub async fn detect_site<R: tauri::Runtime>(…)`
  for (const m of source.matchAll(
    /pub (?:async )?fn (\w+)(?:<[^>]*>)?\s*\(([\s\S]*?)\)\s*(?:->|\{)/g,
  )) {
    const [, name, raw] = m;
    const params = [];
    let depth = 0;
    let current = "";
    for (const ch of raw) {
      if (ch === "<" || ch === "(" || ch === "[") depth += 1;
      else if (ch === ">" || ch === ")" || ch === "]") depth -= 1;
      if (ch === "," && depth === 0) {
        params.push(current);
        current = "";
      } else {
        current += ch;
      }
    }
    if (current.trim()) params.push(current);
    const names = [];
    for (const p of params) {
      const idx = p.indexOf(":");
      if (idx === -1) continue;
      const pname = p.slice(0, idx).trim();
      const ptype = p.slice(idx + 1).trim();
      if (!pname || INJECTED.test(ptype)) continue;
      names.push(pname.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase()));
    }
    map.set(name, names);
  }
  if (map.size === 0) {
    throw new Error("在 commands.rs 里没解析到任何命令签名——解析器坏了，不能当成通过");
  }
  return map;
}

/**
 * `api.ts` 里每个 `invokeCommand("cmd", { … })` 的键集合。
 *
 * **M16-S6b 复审 P1-1 的修法**：旧实现用一条正则
 * `invokeCommand(?:<…>)?\(\s*"cmd"\s*(?:,\s*\{([^}]*)\})?\s*\)`，它有两种静默跳过：
 * ① 多行收尾（`,\n  })`）；② **嵌套花括号**（`{ args: { keep } }` —— `[^}]*` 在第一个 `}` 就停）。
 * 实测 57 个调用点里只解析到 50 个，而汇总行只报「解析到多少」，**不报总数** ⇒ 读者无从发现缺口。
 * 现在改成「扫描 + 花括号配对」，并加**计数自证**：调用点总数与解析数不等就红。
 */
function parseTsInvokeArgs() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const map = new Map();
  let calls = 0;

  /** 顶层逗号切分（忽略嵌套 `{}`/`[]`/`()` 里的逗号）。 */
  const topLevelParts = (body) => {
    const parts = [];
    let depth = 0;
    let current = "";
    for (const ch of body) {
      if (ch === "{" || ch === "[" || ch === "(") depth += 1;
      else if (ch === "}" || ch === "]" || ch === ")") depth -= 1;
      if (ch === "," && depth === 0) {
        parts.push(current);
        current = "";
      } else {
        current += ch;
      }
    }
    if (current.trim()) parts.push(current);
    return parts;
  };

  const re = /invokeCommand(?:<[^>]*>)?\(\s*"([a-z_]+)"/g;
  let m;
  while ((m = re.exec(source)) !== null) {
    calls += 1;
    const cmd = m[1];
    let i = re.lastIndex;
    while (i < source.length && /\s/.test(source[i])) i += 1;
    let keys = [];
    if (source[i] === ",") {
      i += 1;
      while (i < source.length && /\s/.test(source[i])) i += 1;
      if (source[i] === "{") {
        // 花括号配对扫到匹配的 `}`：多行与嵌套都吃得下
        let depth = 0;
        const start = i;
        for (; i < source.length; i += 1) {
          if (source[i] === "{") depth += 1;
          else if (source[i] === "}") {
            depth -= 1;
            if (depth === 0) break;
          }
        }
        keys = topLevelParts(source.slice(start + 1, i))
          .map((part) => part.split(":")[0].trim())
          .filter(Boolean);
      }
    }
    map.set(cmd, keys);
  }

  // 计数自证：调用点总数必须与解析数相等（把「静默漏」变成「显式红」）
  const occurrences = [...source.matchAll(/invokeCommand/g)].length;
  const declarations = [...source.matchAll(/function\s+invokeCommand/g)].length;
  const expected = occurrences - declarations;
  if (calls !== expected) {
    throw new Error(
      `invokeCommand 调用点总数与解析数不一致：文件里有 ${expected} 个调用点，` +
        `只解析到 ${calls} 个（差 ${expected - calls}）。` +
        `有调用点没被参数名守护覆盖——修解析器，不要放过。`,
    );
  }
  if (map.size === 0) {
    throw new Error("在 api.ts 里没解析到任何 invokeCommand 调用——解析器坏了，不能当成通过");
  }
  return map;
}

{
  const rustParams = parseRustCommandParams();
  const tsArgs = parseTsInvokeArgs();
  const problems = [];
  for (const [cmd, keys] of tsArgs) {
    const expected = rustParams.get(cmd);
    if (expected === undefined) {
      // 命令名本身的对账在第 1 节；这里只报「解析不到签名」这种异常
      problems.push(`  ${cmd}: 在 commands.rs 里找不到同名命令签名（解析器或命名不同步）`);
      continue;
    }
    const missing = expected.filter((p) => !keys.includes(p));
    const extra = keys.filter((k) => !expected.includes(k));
    if (missing.length) {
      problems.push(`  ${cmd}: 调用点少了参数 ${missing.join(", ")}（后端形参是 ${expected.join(", ") || "无"}）`);
    }
    if (extra.length) {
      problems.push(
        `  ${cmd}: 调用点多传了 ${extra.join(", ")}（后端形参是 ${expected.join(", ") || "无"}；` +
          `形参名必须 camelCase，写成 snake_case 时 Tauri 反序列化会失败）`,
      );
    }
  }
  if (problems.length) {
    fail(`命令参数名与后端形参不一致（P2-17 G7）：\n${problems.join("\n")}`);
  } else {
    ok(`命令参数名与后端形参一致（${tsArgs.size} 条调用点）`);
  }
}

// ============================================ 9. DTO 字段名与取值对账（B-122）
//
// 这条守护治的是「Rust 改了字段名/取值，TS 类型没跟着改」：两者都不会让任何
// 现有检查变红（`tsc` 只看 TS 侧，cargo 只看 Rust 侧），而界面上表现为
// 「字段永远是 undefined」「开关永远不生效」。
//
// 判据：
// - 每个 Rust camelCase DTO 要么在 TS 侧有同名类型（`XxxDto` → `Xxx`），要么在
//   `DTO_NO_TS` 里**逐条声明**（声明本身就是一次可见的改动）；
// - 配对的字段名集合必须**严格相等**（多一个少一个都红）；
// - 取值集合（`restart_hint_str` / `autostart_state` 的 match 臂）与 TS 联合字面量相等。

/** `XxxDto` 在前端叫别的名字的例外（显式声明，加一行即一次可见改动）。 */
const DTO_ALIASES = {
  KeychainPurgeDto: "KeychainPurgeReport",
  KeyMetaDto: "KeyRow",
  StoredKeyRowDto: "StoredKeyRow",
  DeliveryHistoryDto: "DeliveryRecord",
  GatewayUsageDto: "GatewayUsageRow",
  UsageSnapshotDto: "UsageSnapshotRow",
  DetectProxyDto: "DetectedSystemProxy",
  KeySyncDto: "KeySyncSummary",
  SiteSummaryDto: "SiteRow",
  ConsentDto: "ConsentRow",
  EventDto: "EventRow",
};

/**
 * 后端有、前端**故意**没有对应类型的 DTO（逐条给理由）。
 * 加进来的代价是这一条不再受守护，所以理由必须成立。
 */
const DTO_NO_TS = {
  DiagnosticsArgs: "前端只传 limit 一个字面量，没有对应类型（见 api.ts 的 exportDiagnostics）",
  DiagnosticsResultDto: "诊断包是文件导出，界面只显示路径与字节数",
  DeliveryArgs: "有 TS 类型（DeliveryArgs），但字段名与 Rust 不同：前端传 { keyId, channel, model, mode } 包成 args",
  UpdateSettingsArgs: "前端直接传 Settings 类型（Rust 侧包一层 { settings }）",
  GatewayStartArgs: "前端传 { siteId, keyId }，Rust 侧包成 GatewayStartArgs",
  ExportArgs: "前端传 { password }，Rust 侧包成 ExportArgs",
  PruneArgs: "前端传 { keep }，Rust 侧包成 PruneArgs",
  ProbeArgs: "探针页是诊断工具，字段随探针变化，不逐字对账",
  GatewayUsageDto: "已由 DTO_ALIASES 映射到 GatewayUsageRow",
  UsageSnapshotDto: "已由 DTO_ALIASES 映射到 UsageSnapshotRow",
  DetectProxyDto: "已由 DTO_ALIASES 映射到 DetectedSystemProxy",
  KeySyncDto: "已由 DTO_ALIASES 映射到 KeySyncSummary",
  KeychainPurgeDto: "已由 DTO_ALIASES 映射到 KeychainPurgeReport",
  KeyMetaDto: "已由 DTO_ALIASES 映射到 KeyRow",
  StoredKeyRowDto: "已由 DTO_ALIASES 映射到 StoredKeyRow",
  DeliveryHistoryDto: "已由 DTO_ALIASES 映射到 DeliveryRecord",
};

function parseRustCamelDtos() {
  const source = stripComments(
    readFileSync(join(root, "src-tauri/src/commands.rs"), "utf8"),
  );
  const map = new Map();
  const re =
    /#\[serde\(rename_all = "camelCase"\)\]\s*\n(?:#\[[^\]]*\]\s*\n)*pub struct (\w+)\s*\{([\s\S]*?)\n\}/g;
  for (const m of source.matchAll(re)) {
    const [, name, body] = m;
    const fields = [...body.matchAll(/^\s*(?:pub )?([a-z_][a-z0-9_]*)\s*:/gm)].map((x) =>
      x[1].replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase()),
    );
    map.set(name, new Set(fields));
  }
  if (map.size === 0) {
    throw new Error("在 commands.rs 里没解析到任何 camelCase DTO——解析器坏了，不能当成通过");
  }
  return map;
}

/** TS 类型 → 顶层键集合。手写扫描器是为了正确处理**嵌套对象**（正则会把内层键也算进来）。 */
function parseTsTypes() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const map = new Map();
  const re = /export type (\w+) = \{/g;
  let m;
  while ((m = re.exec(source)) !== null) {
    const name = m[1];
    let depth = 1;
    let i = re.lastIndex;
    let body = "";
    while (i < source.length && depth > 0) {
      const ch = source[i];
      if (ch === "{") depth += 1;
      else if (ch === "}") {
        depth -= 1;
        if (depth === 0) break;
      }
      body += ch;
      i += 1;
    }
    // 顶层键：深度 0 的 `key?:` —— 用同一套括号计数扫一遍。
    // 先把 `;` 换成换行，否则单行类型（`{ alias: string; realModel: string }`）
    // 只会数到第一个键（实测漏过 AliasEntry.realModel）。
    const keys = [];
    let d = 0;
    for (const line of body.replace(/;/g, ";\n").split("\n")) {
      const trimmed = line.trim();
      if (d === 0) {
        const km = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\??\s*:/);
        if (km) keys.push(km[1]);
      }
      for (const ch of line) {
        if (ch === "{" || ch === "(" || ch === "[") d += 1;
        else if (ch === "}" || ch === ")" || ch === "]") d -= 1;
      }
    }
    map.set(name, new Set(keys));
  }
  if (map.size === 0) {
    throw new Error("在 api.ts 里没解析到任何 export type——解析器坏了，不能当成通过");
  }
  return map;
}

/** Rust 侧 `match` 臂的字面量（用于取值集合对账）。 */
function rustMatchLiterals(fnName, file) {
  const source = stripComments(readFileSync(join(root, file), "utf8"));
  const fn = source.match(new RegExp(`fn ${fnName}\\([\\s\\S]*?\\n\\}`));
  if (!fn) throw new Error(`找不到 ${fnName}()`);
  const literals = [...fn[0].matchAll(/=>\s*"([A-Za-z0-9_-]+)"/g)].map((m) => m[1]);
  if (literals.length === 0) {
    throw new Error(`${fnName}() 里没解析到字面量——不能当成通过`);
  }
  return literals;
}

/** TS 联合字面量（`export type X = "a" | "b";`）。 */
function tsUnionLiterals(typeName) {
  const source = stripComments(readFileSync(join(root, "src/lib/api.ts"), "utf8"));
  const m = source.match(new RegExp(`export type ${typeName} =([^;]+);`));
  if (!m) throw new Error(`在 api.ts 里找不到 ${typeName} 联合类型`);
  const literals = [...m[1].matchAll(/"([A-Za-z0-9_-]+)"/g)].map((x) => x[1]);
  if (literals.length === 0) throw new Error(`${typeName} 里没解析到字面量——不能当成通过`);
  return literals;
}

{
  const rustDtos = parseRustCamelDtos();
  const tsTypes = parseTsTypes();
  const problems = [];
  const undeclared = [];
  for (const [dto, rustFields] of rustDtos) {
    const base = dto.replace(/Dto$/, "");
    const tsName =
      DTO_ALIASES[dto] ?? (tsTypes.has(base) ? base : undefined);
    if (!tsName) {
      if (!DTO_NO_TS[dto]) undeclared.push(dto);
      continue;
    }
    const tsFields = tsTypes.get(tsName);
    if (!tsFields) {
      problems.push(`  ${dto} ↔ ${tsName}：api.ts 里没有这个类型`);
      continue;
    }
    const missingInTs = [...rustFields].filter((f) => !tsFields.has(f));
    const extraInTs = [...tsFields].filter((f) => !rustFields.has(f));
    if (missingInTs.length) {
      problems.push(`  ${dto} ↔ ${tsName}：TS 缺字段 ${missingInTs.join(", ")}`);
    }
    if (extraInTs.length) {
      problems.push(`  ${dto} ↔ ${tsName}：TS 多字段 ${extraInTs.join(", ")}`);
    }
  }
  if (undeclared.length) {
    problems.push(
      `  以下 DTO 既没有同名 TS 类型、也没有在 DTO_NO_TS 里声明：${undeclared.join(", ")}\n` +
        `  （新增 DTO 时请在脚本里加一行——声明本身是可见的改动）`,
    );
  }
  // 取值集合
  const valuePairs = [
    ["restart_hint_str", "src-tauri/src/commands.rs", "RestartHint"],
  ];
  for (const [fnName, file, tsName] of valuePairs) {
    const rustValues = rustMatchLiterals(fnName, file).sort();
    const tsValues = tsUnionLiterals(tsName).sort();
    if (rustValues.join("|") !== tsValues.join("|")) {
      problems.push(
        `  ${fnName}() 的取值 [${rustValues.join(", ")}] ≠ ${tsName} 的取值 [${tsValues.join(", ")}]`,
      );
    }
  }
  if (problems.length) {
    fail(`DTO 字段名 / 取值在 Rust ↔ TS 之间不一致（B-122）：\n${problems.join("\n")}`);
  } else {
    ok(`DTO 字段名与取值两边一致（${rustDtos.size} 个 camelCase DTO）`);
  }
}

if (process.exitCode) {
  if (suppressedOk > 0) {
    console.error(`\n（已跳过 ${suppressedOk} 项 ✓ 输出：前面有失败，本次整体未通过。）`);
  }
  console.error("\n命令一致性检查未通过。");
} else {
  console.log("\n命令一致性检查通过。");
}
